function signup(){panel('<h3>Criar conta</h3><p>Crie sua conta RIMAK para salvar seu acesso e usar o ecossistema.</p><form id="rkSignupForm"><input class="rkInput" id="rkEmail" type="email" placeholder="Seu e-mail" required><br><br><input class="rkInput" id="rkPass" type="password" placeholder="Senha (mínimo 6 caracteres)" required><div class="rkRow"><button class="rkBtn primary">Criar conta</button><button class="rkBtn" type="button" id="rkBackLogin">Já tenho conta</button></div><div class="rkMuted" id="rkAuthMsg"></div></form>');$("#rkSignupForm").onsubmit=async function(e){e.preventDefault();$("#rkAuthMsg").textContent="Criando…";try{var d=await auth("auth_signup",{email:$("#rkEmail").value.trim().toLowerCase(),password:$("#rkPass").value});if(d.session){state.user=d.user;state.session=d.session;save();await account();closePanel();toast("Conta criada.")}else $("#rkAuthMsg").textContent="Conta criada. Confirme o e-mail para entrar."}catch(x){$("#rkAuthMsg").textContent=x.message||"Erro ao criar conta."}};$("#rkBackLogin").onclick=login}
